// any step that spans a gap, which could hold daylight.
//
// A counter that falls has been reset, and that one interval is dropped.
// Each day reads one hour before its midnight, so its first interval has a
// reading to start from.
//
// Self-heating packs draw their heaters from the charge current through the
// shunt. That energy is in bank_in_wh and bank_net_wh without being stored.
// It is not in load_wh, which is therefore the loads alone plus the wiring
// loss between the two meters.
//
// The night is wherever every controller reading in a five-minute bin shows
// no panel power. An overcast day still produces, so it is not night. The
// bins are cut in UTC: on the day the clocks fall back, local bins would
// fold the repeated hour onto the first one. Chicago's offsets are whole
// hours, so UTC bins line up with local ones.
//
// ah_net flattens wherever the shunt clamps at full or empty.
//
// solar_wh_check holds each output-power snapshot, one every thirty
// seconds, for the interval it ends, at most five minutes. It misses short
// changes. A large gap from solar_wh means missing controller readings, not
// a better figure. A controller outage across midnight puts its yield in
// solar_wh on the later day.

import "date"
import "timezone"

option location = timezone.location(name: "America/Chicago")

// The shunt's poll interval, from the node's slow_poll_interval. A step
// longer than two and a half of these spans a gap in the readings: one
// missed poll, with its jitter, stays inside.
poll = 60s

start = date.truncate(t: v.timeRangeStart, unit: 1d)
lead = date.sub(d: 1h, from: start)
bin = 5m

node = (device) => from(bucket: "raw")
    |> range(start: lead)
    |> filter(fn: (r) => r._measurement == "blind1" and r.node == "downstairs" and r.device == device)

// One row per field and day, ready to be put side by side.
stat = (tables=<-, name, col) =>
    tables
        |> keep(columns: ["day", col])
        |> rename(fn: (column) => if column == col then "_value" else column)
        |> group(columns: ["day"])
        |> sum()
        |> map(fn: (r) => ({day: r.day, _field: name, _value: float(v: r._value)}))
        |> group()

shunt = node(device: "shunt")
    |> filter(
        fn: (r) =>
            (r._field == "cumulative_energy_wh" or r._field == "charging"
                or
                r._field == "remaining_capacity_ah"),
    )
    |> group()
    |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
    |> filter(fn: (r) => exists r.cumulative_energy_wh and exists r.charging)
    |> sort(columns: ["_time"])

// difference keeps the first reading, with no value, so that elapsed has it
// to drop. Otherwise each would drop a reading of its own, and the rise from
// the first reading to the second, gap and all, would be lost.
steps = shunt
    |> difference(columns: ["cumulative_energy_wh"], nonNegative: true, keepFirst: true)
    |> elapsed(unit: 1s)
    |> filter(fn: (r) => exists r.cumulative_energy_wh and r._time >= start)
    |> map(
        fn: (r) =>
            ({
                _time: r._time,
                gap: r.elapsed * 2 > 5 * int(v: poll) / int(v: 1s),
                secs: float(v: r.elapsed),
                day: date.truncate(t: r._time, unit: 1d),
                bin: date.truncate(t: r._time, unit: bin, location: timezone.utc),
                wh_in: if r.charging > 0.5 then r.cumulative_energy_wh else 0.0,
                wh_out: if r.charging > 0.5 then 0.0 else r.cumulative_energy_wh,
            }),
    )

bank_in = steps |> stat(name: "bank_in_wh", col: "wh_in")
bank_out = steps |> stat(name: "bank_out_wh", col: "wh_out")

coverage = shunt
    |> filter(fn: (r) => r._time >= start)
    |> map(
        fn: (r) => {
            day = date.truncate(t: r._time, unit: 1d)
            next = date.add(d: 1d, to: day)
            end = if next > now() then now() else next
            expected = float(v: int(v: end) - int(v: day)) / float(v: int(v: poll))

            return {day: day, pct: 100.0 / expected}
        },
    )
    |> stat(name: "shunt_coverage_pct", col: "pct")

ah_net = shunt
    |> filter(fn: (r) => exists r.remaining_capacity_ah)
    |> difference(columns: ["remaining_capacity_ah"])
    |> filter(fn: (r) => exists r.remaining_capacity_ah and r._time >= start)
    |> map(fn: (r) => ({day: date.truncate(t: r._time, unit: 1d), ah: r.remaining_capacity_ah}))
    |> stat(name: "ah_net", col: "ah")

mppt = (field) => node(device: "mppt") |> filter(fn: (r) => r._field == field)

solar = mppt(field: "yield_total_kwh")
    |> group()
    |> sort(columns: ["_time"])
    |> difference(nonNegative: true)
    |> filter(fn: (r) => exists r._value and r._time >= start)
    |> map(fn: (r) => ({day: date.truncate(t: r._time, unit: 1d), wh: r._value * 1000.0}))
    |> stat(name: "solar_wh", col: "wh")

solar_check = mppt(field: "battery_watts")
    |> group()
    |> sort(columns: ["_time"])
    |> elapsed(unit: 1s)
    |> filter(fn: (r) => r._time >= start)
    |> map(
        fn: (r) =>
            ({
                day: date.truncate(t: r._time, unit: 1d),
                wh: r._value * float(v: if r.elapsed > 300 then 300 else r.elapsed) / 3600.0,
            }),
    )
    |> stat(name: "solar_wh_check", col: "wh")

dark = mppt(field: "pv_watts")
    |> filter(fn: (r) => r._time >= start)
    |> group()
    |> map(fn: (r) => ({bin: date.truncate(t: r._time, unit: bin, location: timezone.utc), pv: r._value}))
    |> group(columns: ["bin"])
    |> max(column: "pv")
    |> group()
    |> filter(fn: (r) => r.pv <= 0.0)
    |> map(fn: (r) => ({bin: r.bin, day: date.truncate(t: r.bin, unit: 1d), hours: float(v: int(v: bin)) / float(v: int(v: 1h))}))

night_hours = dark |> stat(name: "night_hours", col: "hours")

night_steps = join(
    tables: {
        s: steps |> filter(fn: (r) => not r.gap) |> group() |> drop(columns: ["_time", "day"]),
        d: dark,
    },
    on: ["bin"],
)

night_load = night_steps |> stat(name: "night_load_wh", col: "wh_out")

// The time the kept night steps cover. A gap is out of night_load_wh, so it
// is out of the time the average is taken over too.
night_covered = night_steps |> stat(name: "night_covered_s", col: "secs")

union(
    tables: [
        bank_in,
        bank_out,
        coverage,
        ah_net,
        solar,
        solar_check,
        night_hours,
        night_load,
        night_covered,
    ],
)
    |> group()
    |> pivot(rowKey: ["day"], columnKey: ["_field"], valueColumn: "_value")
    |> map(
        fn: (r) =>
            ({r with
                bank_net_wh: r.bank_in_wh - r.bank_out_wh,
                load_wh: r.solar_wh - (r.bank_in_wh - r.bank_out_wh),
                direct_solar_wh: r.solar_wh - r.bank_in_wh,
                night_avg_w: r.night_load_wh * 3600.0 / r.night_covered_s,
            }),
    )
    |> keep(
        columns: [
            "day",
            "bank_in_wh",
            "bank_out_wh",
            "bank_net_wh",
            "ah_net",
            "solar_wh",
            "load_wh",
            "direct_solar_wh",
            "night_load_wh",
            "night_hours",
            "night_avg_w",
            "solar_wh_check",
            "shunt_coverage_pct",
        ],
    )
    |> sort(columns: ["day"])

// Each pack's share of the bank's current, in percent. A share of almost no
// current swings wildly, so a window is left out while the bank carries less
// than two amps either way. "Chins, by day" is the Chins's share of the
// day's throughput, charge and discharge alike, drawn a day wide. A share
// above 100 or below 0 means one pack is charging the other.

import "date"
import "math"
import "timezone"

option location = timezone.location(name: "America/Chicago")

// The two devices read at different moments, so both are averaged over a
// common window of at least three minutes. A window missing either is left
// out.

w = if int(v: v.windowPeriod) < int(v: 3m) then 3m else v.windowPeriod

amps = from(bucket: "raw")
    |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
    |> filter(
        fn: (r) =>
            r._measurement == "blind1" and r.node == "downstairs"
                and
                (r.device == "bms" and r._field == "pack_amps" or r.device == "shunt" and r._field == "shunt_amps"),
    )
    |> group(columns: ["_field"])
    |> aggregateWindow(every: w, fn: mean, createEmpty: false)
    |> group()
    |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
    |> filter(fn: (r) => exists r.pack_amps and exists r.shunt_amps)

moving = amps |> filter(fn: (r) => math.abs(x: r.shunt_amps) >= 2.0)

// The day's throughput from each reading's size, taken before any averaging,
// so charge and discharge add rather than cancel. The sizes are averaged over
// three-minute windows and only windows holding both devices count, so a gap
// in one device does not tilt the day. Three minutes divides the day, and
// each window counts on the day it starts, so no window crosses midnight and
// a whole day's figure does not change with the dashboard's zoom. A day the
// range cuts holds only the part inside the range.
daily = from(bucket: "raw")
    |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
    |> filter(
        fn: (r) =>
            r._measurement == "blind1" and r.node == "downstairs"
                and
                (r.device == "bms" and r._field == "pack_amps" or r.device == "shunt" and r._field == "shunt_amps"),
    )
    |> map(fn: (r) => ({r with _value: math.abs(x: r._value)}))
    |> group(columns: ["_field"])
    |> aggregateWindow(every: 3m, fn: mean, createEmpty: false, timeSrc: "_start")
    |> group()
    |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
    |> filter(fn: (r) => exists r.pack_amps and exists r.shunt_amps)
    |> map(fn: (r) => ({day: date.truncate(t: r._time, unit: 1d), chins: r.pack_amps, bank: r.shunt_amps}))
    |> group(columns: ["day"])
    |> reduce(
        identity: {chins: 0.0, bank: 0.0},
        fn: (r, accumulator) => ({chins: accumulator.chins + r.chins, bank: accumulator.bank + r.bank}),
    )
    |> group()
    |> filter(fn: (r) => r.bank > 0.0)
    |> map(fn: (r) => ({day: r.day, _value: 100.0 * r.chins / r.bank}))

union(
    tables: [
        moving |> map(fn: (r) => ({_time: r._time, _field: "Chins", _value: 100.0 * r.pack_amps / r.shunt_amps})),
        moving
            |> map(fn: (r) => ({_time: r._time, _field: "Weize pair", _value: 100.0 - 100.0 * r.pack_amps / r.shunt_amps})),
        daily |> map(fn: (r) => ({_time: r.day, _field: "Chins, by day", _value: r._value})),
        daily
            |> map(
                fn: (r) =>
                    ({_time: date.sub(d: 1s, from: date.add(d: 1d, to: r.day)), _field: "Chins, by day", _value: r._value}),
            ),
    ],
)
    |> group(columns: ["_field"])
    |> sort(columns: ["_time"])

// What each of the blind's loads draws, from the last time it was measured.
//
// A load is measured when the controller switches it: the step in the
// bank's current across the switch is the load's draw. Each row is the
// latest such step for a load, with when it was taken, how many were taken
// in the last thirty days, and their average.
//
// The recorder's branch is wired around its relay, so it is never switched.
// Its row is the bank's draw while every relay load has been off for five
// minutes, with no charge coming in. That holds the recorder and everything
// that cannot be shed: the Pi, the network gear, the charge controller and
// the battery radios. The two are not measured apart.
//
// Watts are at a nominal 13.2 V.

import "date"
import "join"
import "strings"
import "timezone"

option location = timezone.location(name: "America/Chicago")

start = -30d

node = (device, fields) => from(bucket: "raw")
    |> range(start: start)
    |> filter(fn: (r) => r._measurement == "blind1" and r.node == "downstairs" and r.device == device and r._field =~ fields)

// The controller's relay loads. The recorder's relay is listed but its
// branch is wired around it, so it is never measured.
relays = node(device: "control", fields: /^powered$/)
    |> filter(fn: (r) => r.load =~ /^(cameras_far|cameras_near|cpu_fan|irrigation|irrigation[.]inverter)$/)

// Switches in one publish are one event. The pump and its inverter start
// and stop together, and that is the pump; any other pair is two loads at
// once and is measured as neither. Each event knows how long since the one
// before it and until the one after, which bounds its windows.
events = relays
    |> group(columns: ["load"])
    |> sort(columns: ["_time"])
    |> elapsed(unit: 1s)
    |> difference()
    |> filter(fn: (r) => r._value != 0.0)
    // A change across a gap in the controller's publishes, such as a
    // restart, happened at some time inside the gap. It still bounds its
    // neighbours' windows, but it is not measured.
    |> map(fn: (r) => ({r with load: if r.elapsed > 45 then "gap" else r.load}))
    |> group(columns: ["_time"])
    |> reduce(
        identity: {n: 0, names: "", dir: 0.0, pump_dir: 0.0},
        fn: (r, accumulator) => ({
            n: accumulator.n + 1,
            names: accumulator.names + r.load + " ",
            dir: r._value,
            pump_dir: if r.load == "irrigation" then r._value else accumulator.pump_dir,
        }),
    )
    |> group()
    |> sort(columns: ["_time"])
    |> map(
        fn: (r) => {
            pump = r.n == 2 and strings.containsStr(v: r.names, substr: "irrigation ")
                and strings.containsStr(v: r.names, substr: "irrigation.inverter ")
            load = if r.n == 1 then strings.trimSpace(v: r.names) else if pump then "irrigation" else "several"

            return {_time: r._time, load: load, dir: if pump then r.pump_dir else r.dir, t: int(v: r._time)}
        },
    )
    |> duplicate(column: "t", as: "t_prev")
    |> difference(columns: ["t_prev"], keepFirst: true)
    |> sort(columns: ["_time"], desc: true)
    |> duplicate(column: "t", as: "t_next")
    |> difference(columns: ["t_next"], keepFirst: true)
    |> sort(columns: ["_time"])
    |> map(
        fn: (r) => ({
            ev: r._time,
            load: r.load,
            dir: r.dir,
            since: if exists r.t_prev then r.t_prev else int(v: 1h),
            until: if exists r.t_next then -r.t_next else int(v: 1h),
        }),
    )
    |> filter(fn: (r) => r.load != "several" and r.load != "gap")

// Each event is offered every thirty-second slot from three minutes before
// it to five minutes after, and a reading meets the events whose slots hold
// it. The events are few, so they are the side that is copied.
slots = (d) => events
    |> map(fn: (r) => ({r with key: date.truncate(t: date.add(d: d, to: r.ev), unit: 30s)}))

offered = union(
    tables: [
        slots(d: -210s), slots(d: -180s), slots(d: -150s), slots(d: -120s),
        slots(d: -90s), slots(d: -60s), slots(d: -30s), slots(d: 0s),
        slots(d: 30s), slots(d: 60s), slots(d: 90s), slots(d: 120s),
        slots(d: 150s), slots(d: 180s), slots(d: 210s), slots(d: 240s),
        slots(d: 270s), slots(d: 300s),
    ],
)

readings = (device, field) => node(device: device, fields: field)
    |> group()
    |> map(fn: (r) => ({_time: r._time, value: r._value, key: date.truncate(t: r._time, unit: 30s)}))

// The controller publishes a switch up to thirty seconds after it makes
// it, so a reading in those thirty seconds before a publish may already
// hold that switch's step, and is used on neither side of it. A camera's
// own start draws more than it runs on, so its after window opens two
// minutes on, and its step is the mean of the readings in it. The pump is
// measured on its first reading after the switch is published, close to
// where the controller checks it. Before an event, the last reading stands.
settle = (load) => if load == "irrigation" then 0 else int(v: 2m)

// The thirty seconds kept clear before the next publish. A run the check
// stops is stopped by the very reading that measures it, so that reading
// always comes before the stop.
margin = (load) => if load == "irrigation" then 0 else int(v: 30s)

side = (l, t) => {
    age = int(v: t) - int(v: l.ev)

    return if age < -int(v: 30s) and -age <= int(v: 3m) and -age < l.since then "before"
        else if age > settle(load: l.load) and age <= int(v: 270s) and age < l.until - margin(load: l.load) then "after"
        else "none"
}

met = (device, field) => join.inner(
    left: offered,
    right: readings(device: device, field: field),
    on: (l, r) => l.key == r.key,
    as: (l, r) => ({ev: l.ev, load: l.load, dir: l.dir, side: side(l: l, t: r._time), _time: r._time, value: r.value}),
)
    |> filter(fn: (r) => r.side != "none")

amps = met(device: "shunt", field: /^shunt_amps$/)
    |> group(columns: ["ev", "load", "dir", "side"])
    |> sort(columns: ["_time"])

used = union(
    tables: [
        amps |> filter(fn: (r) => r.side == "before") |> last(column: "_time"),
        amps |> filter(fn: (r) => r.side == "after" and r.load != "irrigation"),
        amps |> filter(fn: (r) => r.side == "after" and r.load == "irrigation") |> first(column: "_time"),
    ],
)

// Any charge while the step is measured, from the panels or a generator,
// would hide part of it, so such an event is not measured. The charge
// controller is checked from ninety seconds before the switch, which holds
// the shunt reading the step starts from.
charging = union(tables: [
    used |> filter(fn: (r) => r.value > 0.0),
    met(device: "mppt", field: /^battery_amps$/)
        |> filter(fn: (r) => r.value > 0.0)
        |> filter(fn: (r) => r.side == "after" or int(v: r._time) - int(v: r.ev) >= -int(v: 90s)),
])
    |> group()
    |> keep(columns: ["ev"])
    |> distinct(column: "ev")
    |> map(fn: (r) => ({ev: r._value, charging: true}))

steps = used
    |> mean(column: "value")
    |> group()
    |> pivot(rowKey: ["ev", "load", "dir"], columnKey: ["side"], valueColumn: "value")
    |> filter(fn: (r) => exists r.before and exists r.after)

steps_labelled = join.left(
    left: steps,
    right: charging,
    on: (l, r) => l.ev == r.ev,
    as: (l, r) => ({l with charging: exists r.charging}),
)
    |> filter(fn: (r) => not r.charging)
    |> map(
        fn: (r) => {
            amps = (r.before - r.after) * r.dir
            // Hours that are dark, or light, all year here. A camera's
            // infrared lights draw at night, so the two are kept apart, and
            // a switch in the hours between is left out.
            hour = date.hour(t: r.ev)
            when = if hour < 6 or hour >= 21 then "night" else if hour >= 9 and hour < 16 then "day" else "twilight"

            // The pump's classes are the band its check uses in the node
            // file: 30 to 60 A is a pump moving water. Like the check, the
            // step holds the inverter's idle draw, since the last reading
            // before a start almost always comes before the inverter's. A
            // first reading can land in the pump's starting surge, so a
            // high one may be that rather than a stall.
            label = if r.load == "cameras_far" then "Far cameras, " + when
                else if r.load == "cameras_near" then "Near cameras, " + when
                else if r.load == "irrigation" and amps < 30.0 then "Pump, dry"
                else if r.load == "irrigation" and amps > 60.0 then "Pump, stalled or still starting"
                else if r.load == "irrigation" then "Pump, wet (inverter included)"
                else if r.load == "irrigation.inverter" then "Inverter, idle"
                else if r.load == "cpu_fan" then "Pi fan"
                else r.load

            return {label: label, _time: r.ev, amps: amps}
        },
    )
    |> filter(fn: (r) => not strings.hasSuffix(v: r.label, suffix: "twilight"))

// The draw with every relay load off for a whole five minutes, no charge
// coming in and the bank discharging: the recorder, whose branch the relay
// does not switch, and everything that cannot be shed.
window = (tables=<-, fn) => tables
    |> aggregateWindow(every: 5m, fn: fn, createEmpty: false, timeSrc: "_start")
    |> group()

busy = relays
    |> group(columns: ["load"])
    |> window(fn: max)
    |> group(columns: ["_time"])
    |> sum()
    |> group()
    |> map(fn: (r) => ({_time: r._time, kind: "busy", value: r._value}))

rest = union(
    tables: [
        busy,
        node(device: "shunt", fields: /^shunt_amps$/) |> window(fn: mean)
            |> map(fn: (r) => ({_time: r._time, kind: "amps", value: r._value})),
        node(device: "mppt", fields: /^battery_amps$/) |> window(fn: max)
            |> map(fn: (r) => ({_time: r._time, kind: "solar", value: r._value})),
    ],
)
    |> pivot(rowKey: ["_time"], columnKey: ["kind"], valueColumn: "value")
    |> filter(fn: (r) => exists r.busy and exists r.amps and exists r.solar)
    |> filter(fn: (r) => r.busy == 0.0 and r.solar <= 0.0 and r.amps < 0.0)
    |> sort(columns: ["_time"])
    |> map(fn: (r) => ({label: "Recorder and base load", _time: r._time, amps: -r.amps}))

measured = union(tables: [steps_labelled, rest])
    |> group(columns: ["label"])
    |> sort(columns: ["_time"])

stats = measured
    |> reduce(
        identity: {n: 0, total: 0.0},
        fn: (r, accumulator) => ({n: accumulator.n + 1, total: accumulator.total + r.amps}),
    )

join.inner(
    left: measured |> last(column: "_time") |> group(),
    right: stats |> group(),
    on: (l, r) => l.label == r.label,
    as: (l, r) => ({
        load: l.label,
        amps: l.amps,
        watts_at_13v2: l.amps * 13.2,
        measured: l._time,
        times: r.n,
        average_amps: r.total / float(v: r.n),
    }),
)
    |> sort(columns: ["load"])
